def hillcomp(p,S,I):
    Vm,Km,Ki,h=np.exp(p); return Vm*S/(Km*(1+(I/Ki)**h)+S)
def hillnon(p,S,I):
    Vm,Km,Ki,h=np.exp(p); return Vm*S/((Km+S)*(1+(I/Ki)**h))
def hillunc(p,S,I):
    Vm,Km,Ki,h=np.exp(p); return Vm*S/(Km+S*(1+(I/Ki)**h))
for name,f in [('hillcomp',hillcomp),('hillnon',hillnon),('hillunc',hillunc)]:
    best=None
    for b in [0,1]:
        for c in [-1,0]:
            for h in [0,1]:
                r=least_squares(lambda p:f(p,S,I)-v,np.array([np.log(10),b,c,h*1.0]))
                if best is None or r.cost<best.cost: best=r
